1	//! The whole-project answer kept on disk between `extract` runs ([`crate::resolve_cached`]), and what it depends on.
2	//!
3	//! The linked checker reads the disk only through the file system it is given, so a run hands it one that notes every
4	//! question it asks and a digest of each answer: whether a path is a file or a directory, a file's text, a directory's
5	//! entries, a path's metadata and its real path, failed lookups included (the paths module resolution tried and did not
6	//! find). That is everything outside this build that the answer can depend on, the compiler options included (the
7	//! tsconfig and what it extends are read the same way); the build itself, the pinned checker with it, is in the header
8	//! ([`Header`]), and the request (the components, the project root, the tsconfig's path) is in the key. A later run
9	//! asks each question again of the disk, and only when every answer is the same is the kept answer used: any change
10	//! anywhere the checker looked, a new file where it found none included, discards it whole. Nothing is tracked per
11	//! component (ADR 0026: a component's dependency closure is not known), so this is conservative by construction.
12	//!
13	//! A question answered two ways in one run (a file edited while the checker read it) keeps nothing, and so does a run
14	//! that reports a diagnostic (a checker that did not start, a request that timed out).
15	
16	use std::io::Cursor;
17	use std::sync::atomic::{AtomicBool, Ordering};
18	use std::sync::{Arc, Mutex, PoisonError};
19	use std::time::SystemTime;
20	
21	use caliper_docgen_core::types::semantic::SemanticOutcome;
22	use camino::Utf8Path;
23	use rustc_hash::FxHashMap;
24	use serde::{Deserialize, Serialize};
25	use tsrs_vfs::{Entries, FS, FileInfo, osvfs};
26	use xxhash_rust::xxh3::Xxh3;
27	
28	use crate::SemanticRequest;
29	
30	/// The file the answer is kept in, in the cache directory the parse cache uses.
31	pub(crate) const FILE: &str = "checker-answers.msgpack";
32	
33	/// Bump when the file's layout changes in a way the fingerprint would not show.
34	const FORMAT: u32 = 1;
35	
36	/// The largest kept answer read back: `gate-large`'s is about 10 MB.
37	const MAX_BYTES: u64 = 512 * 1024 * 1024;
38	
39	/// A question the checker asked of the file system.
40	#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
41	pub(crate) enum Question {
42	    FileExists(String),
43	    ReadFile(String),
44	    DirectoryExists(String),
45	    Entries(String),
46	    Stat(String),
47	    Realpath(String),
48	}
49	
50	/// The questions a run's checker asked, each with a digest of its answer.
51	#[derive(Default)]
52	pub(crate) struct Reads {
53	    asked: Mutex<FxHashMap<Question, u128>>,
54	    /// A question was answered two ways, or the checker wrote: what it read is not one state of the disk.
55	    unsettled: AtomicBool,
56	}
57	
58	impl Reads {
59	    fn note(&self, question: Question, answer: u128) {
60	        let mut asked = self.asked.lock().unwrap_or_else(PoisonError::into_inner);
61	        match asked.get(&question) {
62	            Some(known) if *known != answer => self.unsettled.store(true, Ordering::Relaxed),
63	            Some(_) => {}
64	            None => {
65	                asked.insert(question, answer);
66	            }
67	        }
68	    }
69	
70	    /// Keeps the run's answer from being kept: the checker was refused a file it read (see `checker::TsrsSession`), so
71	    /// its answer is not the one the disk's files make.
72	    pub(crate) fn spoil(&self) {
73	        self.unsettled.store(true, Ordering::Relaxed);
74	    }
75	
76	    /// Every question and answer digest, sorted, when the run read one state of the disk.
77	    fn settled(&self) -> Option<Vec<(Question, u128)>> {
78	        if self.unsettled.load(Ordering::Relaxed) {
79	            return None;
80	        }
81	        let asked = self.asked.lock().unwrap_or_else(PoisonError::into_inner);
82	        let mut reads: Vec<(Question, u128)> =
83	            asked.iter().map(|(question, answer)| (question.clone(), *answer)).collect();
84	        reads.sort_by(|a, b| a.0.cmp_key().cmp(&b.0.cmp_key()));
85	        Some(reads)
86	    }
87	}
88	
89	impl Question {
90	    fn cmp_key(&self) -> (u8, &str) {
91	        match self {
92	            Question::FileExists(path) => (0, path),
93	            Question::ReadFile(path) => (1, path),
94	            Question::DirectoryExists(path) => (2, path),
95	            Question::Entries(path) => (3, path),
96	            Question::Stat(path) => (4, path),
97	            Question::Realpath(path) => (5, path),
98	        }
99	    }
100	
101	    /// The digest of what `fs` answers to this question now.
102	    fn answer(&self, fs: &dyn FS) -> u128 {
103	        match self {
104	            Question::FileExists(path) => flag(fs.file_exists(path)),
105	            Question::ReadFile(path) => text(fs.read_file(path).as_deref()),
106	            Question::DirectoryExists(path) => flag(fs.directory_exists(path)),
107	            Question::Entries(path) => entries(&fs.get_accessible_entries(path)),
108	            Question::Stat(path) => stat(fs.stat(path).as_ref()),
109	            Question::Realpath(path) => text(Some(&fs.realpath(path))),
110	        }
111	    }
112	}
113	
114	fn flag(answer: bool) -> u128 {
115	    u128::from(answer)
116	}
117	
118	fn text(answer: Option<&str>) -> u128 {
119	    let mut hasher = Xxh3::new();
120	    match answer {
121	        Some(text) => {
122	            hasher.update(&[1]);
123	            hasher.update(text.as_bytes());
124	        }
125	        None => hasher.update(&[0]),
126	    }
127	    hasher.digest128()
128	}
129	
130	/// The entries in the order the file system gave them, each list closed by its length, symlinks included.
131	fn entries(answer: &Entries) -> u128 {
132	    let mut hasher = Xxh3::new();
133	    let mut list = |names: &mut dyn Iterator<Item = &String>| {
134	        let mut count = 0u64;
135	        for name in names {
136	            hasher.update(name.as_bytes());
137	            hasher.update(&[0]);
138	            count += 1;
139	        }
140	        hasher.update(&count.to_le_bytes());
141	    };
142	    list(&mut answer.files.iter());
143	    list(&mut answer.directories.iter());
144	    match &answer.symlinks {
145	        Some(symlinks) => {
146	            let mut sorted: Vec<&String> = symlinks.iter().collect();
147	            sorted.sort();
148	            list(&mut sorted.into_iter());
149	        }
150	        None => list(&mut std::iter::once(&String::from("\u{0}none"))),
151	    }
152	    hasher.digest128()
153	}
154	
155	/// Every field of the metadata, the modification time included: a file touched since is a change, though its text may
156	/// not be.
157	fn stat(answer: Option<&FileInfo>) -> u128 {
158	    let mut hasher = Xxh3::new();
159	    match answer {
160	        Some(info) => {
161	            hasher.update(&[1]);
162	            hasher.update(info.name.as_bytes());
163	            hasher.update(&[0]);
164	            hasher.update(&info.size.to_le_bytes());
165	            hasher.update(&info.mode.bits().to_le_bytes());
166	            let modified = info.mod_time.and_then(|time| time.duration_since(SystemTime::UNIX_EPOCH).ok());
167	            hasher.update(&modified.map_or(u128::MAX, |since| since.as_nanos()).to_le_bytes());
168	        }
169	        None => hasher.update(&[0]),
170	    }
171	    hasher.digest128()
172	}
173	
174	/// The file system the linked checker reads through, noting each question it asks of `inner` and the answer's digest
175	/// in `reads`.
176	pub(crate) struct Recording<T> {
177	    pub(crate) inner: T,
178	    pub(crate) reads: Arc<Reads>,
179	}
180	
181	impl<T: FS> FS for Recording<T> {
182	    fn use_case_sensitive_file_names(&self) -> bool {
183	        self.inner.use_case_sensitive_file_names()
184	    }
185	
186	    fn file_exists(&self, path: &str) -> bool {
187	        let answer = self.inner.file_exists(path);
188	        self.reads.note(Question::FileExists(path.to_string()), flag(answer));
189	        answer
190	    }
191	
192	    fn read_file(&self, path: &str) -> Option<String> {
193	        let answer = self.inner.read_file(path);
194	        self.reads.note(Question::ReadFile(path.to_string()), text(answer.as_deref()));
195	        answer
196	    }
197	
198	    fn write_file(&self, path: &str, data: &str) -> Result<(), String> {
199	        self.reads.unsettled.store(true, Ordering::Relaxed);
200	        self.inner.write_file(path, data)
201	    }
202	
203	    fn append_file(&self, path: &str, data: &str) -> Result<(), String> {
204	        self.reads.unsettled.store(true, Ordering::Relaxed);
205	        self.inner.append_file(path, data)
206	    }
207	
208	    fn remove(&self, path: &str) -> Result<(), String> {
209	        self.reads.unsettled.store(true, Ordering::Relaxed);
210	        self.inner.remove(path)
211	    }
212	
213	    fn chtimes(&self, path: &str, a_time: SystemTime, m_time: SystemTime) -> Result<(), String> {
214	        self.reads.unsettled.store(true, Ordering::Relaxed);
215	        self.inner.chtimes(path, a_time, m_time)
216	    }
217	
218	    fn directory_exists(&self, path: &str) -> bool {
219	        let answer = self.inner.directory_exists(path);
220	        self.reads.note(Question::DirectoryExists(path.to_string()), flag(answer));
221	        answer
222	    }
223	
224	    fn get_accessible_entries(&self, path: &str) -> Entries {
225	        let answer = self.inner.get_accessible_entries(path);
226	        self.reads.note(Question::Entries(path.to_string()), entries(&answer));
227	        answer
228	    }
229	
230	    fn stat(&self, path: &str) -> Option<FileInfo> {
231	        let answer = self.inner.stat(path);
232	        self.reads.note(Question::Stat(path.to_string()), stat(answer.as_ref()));
233	        answer
234	    }
235	
236	    fn realpath(&self, path: &str) -> String {
237	        let answer = self.inner.realpath(path);
238	        self.reads.note(Question::Realpath(path.to_string()), text(Some(&answer)));
239	        answer
240	    }
241	}
