243	/// What a kept answer was made by: this build (its sources, the locked dependencies and with them the pinned checker),
244	/// and the request.
245	#[derive(Debug, PartialEq, Serialize, Deserialize)]
246	struct Header {
247	    format: u32,
248	    version: String,
249	    fingerprint: String,
250	    request: u128,
251	}
252	
253	impl Header {
254	    fn of(request: u128) -> Header {
255	        Header {
256	            format: FORMAT,
257	            version: env!("CARGO_PKG_VERSION").to_string(),
258	            fingerprint: env!("CALIPER_SEMANTIC_FINGERPRINT").to_string(),
259	            request,
260	        }
261	    }
262	}
263	
264	/// A digest of everything in the request that the answer depends on: the components with all the structural pass
265	/// says of them, the project root (the checker's working directory), the tsconfig's path and the query order.
266	pub(crate) fn request_key(request: &SemanticRequest) -> u128 {
267	    fn sorted(names: &rustc_hash::FxHashSet<String>) -> Vec<&String> {
268	        let mut names: Vec<&String> = names.iter().collect();
269	        names.sort();
270	        names
271	    }
272	    let targets: Vec<_> = request
273	        .targets
274	        .iter()
275	        .map(|target| {
276	            let wanted = target.react_wanted.as_ref().map(sorted);
277	            (&target.key, &target.file_path, &target.display_name, &target.exports, sorted(&target.described), wanted)
278	        })
279	        .collect();
280	    let described = format!("{:?}", (&request.project_root, &request.tsconfig, targets, request.reverse_queries));
281	    let mut hasher = Xxh3::new();
282	    hasher.update(described.as_bytes());
283	    hasher.digest128()
284	}
285	
286	/// The answer kept at `file` for the request `key` names, when every question its checker asked of the disk has the
287	/// same answer now; `None` otherwise, or when there is none, or it cannot be read.
288	pub(crate) fn load(file: &Utf8Path, key: u128) -> Option<SemanticOutcome> {
289	    let size = std::fs::metadata(file).ok()?.len();
290	    if size > MAX_BYTES {
291	        return None;
292	    }
293	    let bytes = std::fs::read(file).ok()?;
294	    let mut decoder = rmp_serde::Deserializer::new(Cursor::new(bytes.as_slice()));
295	    if Header::deserialize(&mut decoder).ok()? != Header::of(key) {
296	        return None;
297	    }
298	    let reads = Vec::<(Question, u128)>::deserialize(&mut decoder).ok()?;
299	    let at = usize::try_from(decoder.get_ref().position()).ok()?;
300	    if !still_holds(&reads) {
301	        return None;
302	    }
303	    SemanticOutcome::from_bytes(bytes.get(at..)?).ok()
304	}
305	
306	/// Whether the disk answers every question as it did, asked on as many threads as the machine has.
307	fn still_holds(reads: &[(Question, u128)]) -> bool {
308	    let fs = osvfs::fs();
309	    let threads = std::thread::available_parallelism().map_or(1, |count| count.get()).min(16);
310	    let chunk = reads.len().div_ceil(threads).max(1);
311	    std::thread::scope(|scope| {
312	        let checks: Vec<_> = reads
313	            .chunks(chunk)
314	            .map(|part| scope.spawn(move || part.iter().all(|(question, answer)| question.answer(fs) == *answer)))
315	            .collect();
316	        checks.into_iter().all(|check| check.join().unwrap_or(false))
317	    })
318	}
319	
320	/// Keeps `outcome` at `file` for the request `key` names, with the questions `reads` noted. Nothing is kept for an
321	/// outcome with a diagnostic or a run that read more than one state of the disk; a failure to write is logged and
322	/// otherwise ignored (the next run asks the checker again).
323	pub(crate) fn save(file: &Utf8Path, key: u128, reads: &Reads, outcome: &SemanticOutcome) {
324	    if !outcome.diagnostics.is_empty() {
325	        return;
326	    }
327	    let Some(reads) = reads.settled() else {
328	        tracing::debug!("the checker read a file that changed during the run; its answer is not kept");
329	        return;
330	    };
331	    let written = (|| -> Result<(), String> {
332	        let mut bytes = rmp_serde::to_vec(&Header::of(key)).map_err(|error| error.to_string())?;
333	        bytes.extend(rmp_serde::to_vec(&reads).map_err(|error| error.to_string())?);
334	        bytes.extend(outcome.to_bytes()?);
335	        let dir = file.parent().ok_or_else(|| "no directory".to_string())?;
336	        std::fs::create_dir_all(dir).map_err(|error| error.to_string())?;
337	        // A name of its own per process, so two runs sharing the directory do not write one temporary file.
338	        let temporary = dir.join(format!("{FILE}.{}.tmp", std::process::id()));
339	        let result = std::fs::write(&temporary, &bytes).and_then(|()| std::fs::rename(&temporary, file));
340	        if result.is_err() {
341	            std::fs::remove_file(&temporary).ok();
342	        }
343	        result.map_err(|error| error.to_string())
344	    })();
345	    if let Err(error) = written {
346	        tracing::debug!("could not keep the checker's answer at {file}: {error}");
347	    }
348	}
