/// Serialize an [`IncrementalUpdate`] to a JSON string (same reason as above).
pub fn incremental_update_to_json(update: &IncrementalUpdate) -> Result<String, serde_json::Error> {
    serde_json::to_string(update)
}

// ─── Main cold extraction ─────────────────────────────────────────────────────

/// Stateless extraction — suitable for CLI and NAPI cold runs.
pub fn extract(options: &PipelineOptions) -> ExtractionOutput {
    revision::Revision::cold_output(options)
}

// ─── Helper functions ─────────────────────────────────────────────────────────

/// Parse-or-load-from-cache a single `.d.ts` file and merge it into `global`,
/// draining any diagnostics the parse produced into `diagnostics` first —
/// matching how the main per-project-file loop (Phase 3) already handles this.
/// Shared by the Full-mode `@types/react` merge (Phase 3.5) and the ambient
/// `lib.d.ts` merge (Phase 3.6), which previously each merged the parsed data
/// directly with no diagnostics drain at all: an excessive-nesting trip or a
/// parse error while parsing either file would have been silently discarded,
/// since `GlobalSourceData` itself has no diagnostics field to catch it later.
#[cfg(test)]
pub(super) fn merge_cached_dts_file(
    path: &Utf8Path,
    cache: &DtsCache,
    global: &mut GlobalSourceData,
    diagnostics: &mut Vec<Diagnostic>,
) {
    merge_parsed_dts_file(path, parse_cached_dts_file(path, cache), global, diagnostics);
}

/// Read and parse one declaration file through the cache. An unreadable file is an error and is not parsed: parsing ""
/// instead would cache an empty result under this path.
pub(super) fn parse_cached_dts_file(path: &Utf8Path, cache: &DtsCache) -> Result<SourceData, Diagnostic> {
    let source = std::fs::read_to_string(path).map_err(|error| Diagnostic::io_read_error(path, &error))?;
    Ok(match cache.get(path, &source) {
        Some(cached) => cached,
        None => {
            let data = crate::extractor::parse_file(path, &source);
            cache.insert(path, &source, data.clone());
            data
        }
    })
}

/// [`parse_cached_dts_file`]'s result merged into `global`, with the parse's diagnostics (or the read error) added to
/// `diagnostics`. Split from the parse so a run can parse these files while it parses the project's.
pub(super) fn merge_parsed_dts_file(
    path: &Utf8Path,
    parsed: Result<SourceData, Diagnostic>,
    global: &mut GlobalSourceData,
    diagnostics: &mut Vec<Diagnostic>,
) {
    let mut data = match parsed {
        Ok(data) => data,
        Err(diagnostic) => {
            diagnostics.push(diagnostic);
            return;
        }
    };
    diagnostics.append(&mut data.diagnostics);
    // These files exist to resolve types, not to document components: `@types/react`'s
    // own `class PureComponent<P, ...> extends Component<P, ...>` otherwise matches the
    // class-component detector and surfaces as a 0-prop component plus an unresolvable `P`.
    data.component_mappings.clear();
    global.merge(path, data);
}

/// Resolve `mappings` in parallel. The whole closure body is wrapped in `contain_panic` so one component's resolution
/// panicking degrades to a per-component diagnostic instead of poisoning the `.collect()` and losing every other
/// component. Shared by `extract()` and `WatchSession::update_file` so the two cannot drift.
pub(super) fn resolve_guarded(
    mappings: &[&ComponentMapping],
    ctx: &ResolutionContext,
) -> Vec<(ComponentEntry, ResolvedDiagnostics, crate::resolver::Dependencies)> {
    mappings
        .par_iter()
        .copied()
        .map(|mapping| {
            let label = format!("resolve:{}", mapping.component_name);
            crate::panic_guard::contain_panic(&label, || {
                #[cfg(test)]
                if mapping.component_name == RESOLVE_PANIC_TEST_SENTINEL {
                    panic!("simulated resolve-phase panic (test-only sentinel)");
                }

                crate::resolver::resolve_component_tracked(mapping, ctx)
            })
///
/// Freeing a large project's converters, interner and snapshot one allocation at a time costs tens of milliseconds
/// that a process about to exit spends waiting for nothing. [`Teardown::OneShot`] is for that process alone (the CLI's
/// `extract`): it forgets what the run built instead of dropping it, and does not ask the checker to release its
/// snapshot, which the checker's shutdown takes down anyway. Anything that outlives the run (a watch, a Storybook
/// session, the binding, a command that keeps running) must use [`Teardown::Session`], which is the default.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Teardown {
    /// The process ends when the run does: forget the run's memory and do not release its snapshot.
    OneShot,
    /// The process goes on: free the run's memory and release its snapshot.
    #[default]
    Session,
}

/// One whole-project request to the checker: the components to answer for, and how to ask. Built with
/// [`SemanticRequest::new`] and answered by [`resolve`].
#[derive(Debug, Clone)]
pub struct SemanticRequest {
    /// Where the checker finds `node_modules`: its working directory.
    pub project_root: Utf8PathBuf,
    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
    pub tsconfig: Option<Utf8PathBuf>,
    /// The components to ask about.
    pub targets: Vec<Target>,
    /// Bound on each request.
    pub request_timeout: Duration,
    /// Write every request and its answer here as JSON; the tests read it to count and inspect the calls a run makes.
    pub record_to: Option<Utf8PathBuf>,
    /// Ask the checker about a component's props, and about the members of each type, last to first. The answer must
    /// not change: no id the checker hands out, and so no order of queries, may show in it. The tests set this.
    pub reverse_queries: bool,
    teardown: Teardown,
}

impl SemanticRequest {
    /// A request for `targets` under `project_root`, with a 60 second timeout and no tsconfig.
    pub fn new(project_root: Utf8PathBuf, targets: Vec<Target>) -> Self {
        Self {
            project_root,
            tsconfig: None,
            targets,
            request_timeout: Duration::from_secs(60),
            record_to: None,
            reverse_queries: false,
            teardown: Teardown::Session,
        }
    }

    /// The request with `teardown` as what the run does with its memory and snapshot when done ([`Teardown`]).
    #[must_use]
    pub fn with_teardown(mut self, teardown: Teardown) -> Self {
        self.teardown = teardown;
        self
    }
}

/// Resolves the request's components with the checker. Blocks; builds its own runtime, so it must not be called from
/// inside one. The runtime has up to four threads: the built-in checker answers two programs at once, each on a thread
/// of its own, and while it does, the answers it gave the other files in flight are read and converted on these.
pub fn resolve(request: SemanticRequest) -> SemanticOutcome {
    resolve_noting(request, None)
}

/// [`resolve`], with the answer kept in `cache_dir` for the next run over the same request: a run whose checker would
/// read the disk exactly as the last one did gets the last one's answer without starting the checker. Every question
/// that checker asked of the file system (each file it read or looked for, each directory it listed, the tsconfig and
/// what it extends) is asked again first, and any different answer, a new file where it found none included, discards
/// the kept answer whole; so does another build of Caliper or of the pinned checker, and another request. A request
/// that records its calls is answered as [`resolve`] answers it, and nothing is kept for it. The answer is the one
/// [`resolve`] gives, and it is written before the call returns, whatever the request's [`Teardown`].
pub fn resolve_cached(request: SemanticRequest, cache_dir: &Utf8Path) -> SemanticOutcome {
    if request.record_to.is_some() {
        return resolve(request);
    }
    let file = cache_dir.join(kept::FILE);
    let key = kept::request_key(&request);
    let started = std::time::Instant::now();
    if let Some(outcome) = kept::load(&file, key) {
        tracing::debug!(ms = started.elapsed().as_millis() as u64, "the checker's kept answer still holds");
        return outcome;
    }
    let reads = Arc::new(kept::Reads::default());
    let outcome = resolve_noting(request, Some(reads.clone()));
    kept::save(&file, key, &reads, &outcome);
    outcome
}

fn resolve_noting(request: SemanticRequest, reads: Option<Arc<kept::Reads>>) -> SemanticOutcome {
    let threads = std::thread::available_parallelism().map_or(1, |count| count.get().min(CONVERTER_THREADS));
    let built = tokio::runtime::Builder::new_multi_thread().worker_threads(threads).enable_all().build();
    let runtime = match built {
        Ok(runtime) => runtime,
        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
    };
    let teardown = request.teardown;
    let outcome = runtime.block_on(run_noting(request, None, reads));
    if teardown == Teardown::OneShot {
        // Dropping the runtime waits for its threads to wind down.
        std::mem::forget(runtime);
    }
    outcome
}

/// The exported targets by file, in first-seen order, and an outcome that already holds a fallback for each target
/// the checker cannot be asked about.
fn group_by_file(request: &SemanticRequest) -> (SemanticOutcome, FxHashMap<&Utf8Path, Vec<&Target>>, Vec<&Utf8Path>) {
    let mut outcome = SemanticOutcome::default();
    let mut by_file: FxHashMap<&Utf8Path, Vec<&Target>> = FxHashMap::default();
    let mut order: Vec<&Utf8Path> = Vec::new();
    for target in &request.targets {
        if target.exports.is_empty() {
            outcome.fallbacks.push(fallback_of(target, "not exported by its module"));
            continue;
        }
        let group = by_file.entry(target.file_path.as_path()).or_default();
        if group.is_empty() {
            order.push(target.file_path.as_path());
        }
        group.push(target);
    }
    (outcome, by_file, order)
}

/// Answers `request` with a checker started for it, asking `programs` programs at once, or by default as many as
/// [`CHECKER_PROGRAMS`] and the files allow ([`MIN_FILES_PER_PROGRAM`]).
#[cfg(test)]
async fn run(request: SemanticRequest, programs: Option<usize>) -> SemanticOutcome {
    run_noting(request, programs, None).await
}

/// [`run`], the linked checker noting what it reads in `reads` ([`kept`]).
async fn run_noting(
    request: SemanticRequest,
    programs: Option<usize>,
    reads: Option<Arc<kept::Reads>>,
) -> SemanticOutcome {
    if request.targets.iter().all(|target| target.exports.is_empty()) {
        return group_by_file(&request).0;
    }
    let files = group_by_file(&request).2.len();
    let programs = programs.unwrap_or_else(|| CHECKER_PROGRAMS.min(files.div_ceil(MIN_FILES_PER_PROGRAM))).max(1);
    let checker = match Backend::start_noting(&request.project_root, programs, reads) {
        Ok(checker) => checker,
        Err(reason) => return SemanticOutcome::unavailable(reason),
    };
    let outcome = answer_with(&checker, &request).await;
    checker.shutdown().await;
    outcome
}

/// The files of the request's exported targets, in first-seen order: the roots of the program that answers it.
fn root_files(request: &SemanticRequest) -> Vec<String> {
    group_by_file(request).2.iter().map(|file| file.to_string()).collect()
}

/// Answers the request's targets with a checker that is already running: one snapshot of as many programs rooted at
/// their files as the checker answers at once ([`Backend::parallel_programs`]), released once they are answered.
async fn answer_with(checker: &Backend, request: &SemanticRequest) -> SemanticOutcome {
    let files = root_files(request);
    if files.is_empty() {
        return group_by_file(request).0;
    }
    let started = std::time::Instant::now();
    let tsconfig = request.tsconfig.as_ref().map(|path| path.as_str());
    let count = checker.parallel_programs();
    let record = request.record_to.is_some();
    let opened = Rpc::open_programs(checker.client(), request.request_timeout, tsconfig, &files, record, count).await;
    let programs: Vec<Arc<Rpc>> = match opened {
        Ok(programs) => programs.into_iter().map(Arc::new).collect(),
        Err(error) => return SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),

toolUseResult.stdout:
}

