        match joined {
            Ok(Ok((mut answered, mut instantiations))) => {
                outcome.components.append(&mut answered.components);
                outcome.fallbacks.append(&mut answered.fallbacks);
                generic.append(&mut instantiations);
            }
            Ok(Err(error)) => {
                failure = Some(error);
                tasks.abort_all();
            }
